"Três passos para o app começar a mostrar o seu mês. Dá para pular e fazer depois.":"Three steps for the app to start showing your month. You can skip and do it later.",
"Importe de uma planilha .xlsx, .ods ou .csv: o app entende o jeito dela e mostra tudo antes de importar.":"Import from a .xlsx, .ods or .csv spreadsheet: the app understands its layout and shows everything before importing.",
"Boas-vindas!":"Welcome!",
"O nome aparece no topo do Resumo e nas mensagens do app. Fica só neste app: numa conta compartilhada, cada pessoa vê o próprio nome no seu celular.":"Your name appears at the top of the Summary and in app messages. It stays only in this app: in a shared account, each person sees their own name on their phone.",
"Digite o seu nome (ou um apelido).":"Type your name (or a nickname).",
"Este é o Cofrim: seus ganhos, gastos, contas e investimentos num lugar só, salvos na sua conta Google. Veja em um minuto como usar.":"This is Cofrim: your income, expenses, bills and investments in one place, saved in your Google account. See how to use it in one minute.",
"Toque no + (ou nos atalhos do Resumo) e informe só o valor e a categoria; o resto fica em \"Mais opções\". Os gastos que você mais repete viram botões.":"Tap + (or the Summary shortcuts) and enter just the amount and category; the rest is under \"More options\". The expenses you repeat most become buttons.",
"Num salário, escolha em Mais opções o dia em que cai, como o 5º dia útil.":"For a salary, choose the day it arrives in More options, like the 5th business day.",
"Gastos do mês e do ano, contas a vencer, gastos por categoria e contas bancárias. Há muito mais (previsão, gráficos, metas, investimentos): toque em \"Ver mais informações no resumo\", no fim da tela, ou no menu (três barras), no topo › Reorganizar esta tela.":"Expenses for the month and year, bills due, expenses by category and bank accounts. There's much more (forecast, charts, goals, investments): tap \"See more info in the summary\" at the bottom of the screen, or the menu (three bars) at the top › Rearrange this screen.",
"Separados em Assinaturas, Fixos e anuais, Parceladas e Ocasionais, com busca e filtros. Deslize um lançamento para a esquerda para excluir; numa conta com vencimento, para a direita marca como paga. Na mesma aba ficam o orçamento, as previsões de gastos e a saúde financeira do mês.":"Split into Subscriptions, Fixed and yearly, Installments and One-off, with search and filters. Swipe an entry left to delete; on a bill with a due date, swiping right marks it as paid. The budget, expense forecasts and the month's financial health are on the same tab.",
"Lançamento automático e extratos":"Automatic entries and bank statements",
"No Android, as compras e os Pix avisados pelo banco viram sugestões de gasto no Resumo: um toque lança. Em Gastos › Importar extrato, escolha um ou vários arquivos OFX ou CSV do banco e confira antes de importar.":"On Android, purchases and Pix payments notified by your bank become expense suggestions in the Summary: one tap adds them. In Expenses › Import statement, choose one or more OFX or CSV files from your bank and check them before importing.",
"Parcelas e financiamentos":"Installments and financing",
"Em Gastos › Parceladas, cadastre compras parceladas, financiamentos e empréstimos. Toque num item para ver o saldo devedor e todas as parcelas, pagar, abater ou exportar em PDF.":"In Expenses › Installments, add installment purchases, financing and loans. Tap an item to see the outstanding balance and all installments, pay, pay down or export to PDF.",
"Cadastre aplicações, ações e metas. O app projeta quanto vão render com CDI, Selic e IPCA e mostra quanto falta para cada meta.":"Add investments, stocks and goals. The app projects how much they'll earn with CDI, Selic and IPCA and shows how much is left for each goal.",
"Pergunte \"quanto gastei com mercado este mês?\" ou escreva (ou fale) \"gastei 30 no almoço\" para lançar sem abrir formulário.":"Ask \"how much did I spend on groceries this month?\" or write (or say) \"spent 30 on lunch\" to add an entry without opening a form.",
"Com um tema especial, quem responde é o personagem do tema, com as falas dele.":"With a special theme, the theme's character answers, with its own lines.",
"Começam desligados neste aparelho. Ligue em Configurações › Lembretes (o Android pede a permissão de notificações) e escolha os tipos: contas a vencer, antes e no dia, parcelas de financiamentos e os avisos das previsões de gastos. Desligue a economia de bateria do app para os avisos chegarem na hora.":"They start off on this device. Turn them on in Settings › Reminders (Android asks for notification permission) and choose the types: bills due, before and on the day, financing installments and expense forecast alerts. Turn off battery saving for the app so alerts arrive on time.",
"Tudo sincroniza com a sua conta Google, com uma cópia por dia. Em Configurações › Conta compartilhada, dá para dividir os dados com outra pessoa.":"Everything syncs with your Google account, with one backup per day. In Settings › Shared account, you can share your data with another person.",
"Mais de 180 temas especiais, cada um com personagem, cenário animado e estilo de interface próprios, além de cores, moeda e país,":"More than 180 special themes, each with its own character, animated scene and interface style, plus colors, currency and country,",
"abas do menu, bloqueio com senha, widgets na tela inicial (com ou sem os valores) e o modo divertido, com mais de 100 conquistas. Tudo em Configurações.":"menu tabs, password lock, home screen widgets (with or without amounts) and fun mode, with more than 100 achievements. All in Settings.",
