"1. OFX (recomendado)":"1. OFX (recommended)",
"É o formato \"OFX\" ou \"Money\" que quase todo banco oferece ao exportar o extrato. Não precisa ajustar nada.":"It's the \"OFX\" or \"Money\" format that almost every bank offers when exporting the statement. No adjustments needed.",
"2. CSV (planilha em texto)":"2. CSV (text spreadsheet)",
"A primeira linha precisa ter os nomes das colunas, separadas por ponto e vírgula ou vírgula:":"The first line must have the column names, separated by semicolons or commas:",
"Data":"Date",
"(obrigatória)":"(required)",
"31/12/2026 ou 2026-12-31":"31/12/2026 or 2026-12-31",
"-45,90 ou 1200.00":"-45,90 or 1200.00",
"(opcional)":"(optional)",
"também Histórico ou Título":"also History or Title",
"Exemplo:":"Example:",
"Data;Descrição;Valor":"Date;Description;Amount",
"05/10/2026;Mercado;-182,40":"05/10/2026;Groceries;-182,40",
"06/10/2026;Salário;3500,00":"06/10/2026;Salary;3500,00",
"Valores negativos entram como gastos e positivos como ganhos (numa fatura de cartão é o contrário; você escolhe na próxima tela). Antes de gravar, o app mostra a lista para você conferir e desmarca o que já existe.":"Negative amounts come in as expenses and positive ones as income (on a credit card bill it's the opposite; you choose on the next screen). Before saving, the app shows the list for you to check and unchecks what already exists.",
"Dá para escolher vários extratos de uma vez (meses ou bancos diferentes): cada lançamento entra no dia e no mês da data dele, e o que aparece em dois arquivos entra uma vez só.":"You can choose several statements at once (different months or banks): each entry goes on the day and month of its date, and what appears in two files is added only once.",
