"O saldo soma os ganhos e desconta os gastos em que o campo de banco/conta tiver exatamente este nome. Lançamentos com dia depois de hoje ainda não contam, e compras no crédito só saem quando a fatura é paga (configure em Gastos → Faturas do cartão).":"The balance adds up income and subtracts expenses where the bank/account field has exactly this name. Entries dated after today don't count yet, and credit card purchases only come out when the bill is paid (set up in Expenses → Card bills).",
