"O dia de guardar vai de 1 a 28.":"The saving day is from 1 to 28.",
"{}: de {} para {}":"{}: from {} to {}",
"— limite por mês":"— monthly limit",
"Com \"Sim\", se você gastar menos que o limite de uma categoria, a diferença soma ao limite dela no mês seguinte.":"With \"Yes\", if you spend less than a category's limit, the difference is added to its limit the following month.",
"— dia de fechamento":"— closing day",
"— dia de pagamento da fatura":"— bill payment day",
"— limite do cartão (opcional)":"— card limit (optional)",
"— conta que paga a fatura":"— account that pays the bill",
"Fechamento: compras avulsas com dia depois dele entram na fatura do mês seguinte. Pagamento: a fatura de um mês sai da conta no mês seguinte, nesse dia (sem dia, no começo do mês).":"Closing: one-off purchases made after that day go on the next month's bill. Payment: a month's bill comes out of the account the following month, on that day (with no day, at the start of the month).",
"previsão":"forecast",
"Valor previsto":"Expected amount",
