"Sim, todo mês":"Yes, every month",
"O dia final vai de 1 a 31.":"The end day is from 1 to 31.",
"Sem dia, vale até o último dia do mês. Os gastos da categoria (ou todos os gastos, ou tudo no cartão de crédito, nas opções gerais) até esse dia enchem a barra; o que faltar do previsto já entra no saldo previsto do mês.":"With no day, it lasts until the last day of the month. The category's expenses (or all expenses, or everything on the credit card, in the general options) up to that day fill the bar; whatever is left of the expected amount already goes into the month's forecast balance.",
"{}: cotação atual {}. Deixe em branco para desligar.":"{}: current quote {}. Leave blank to turn off.",
"O valor de baixo precisa ser menor que o de cima.":"The lower value must be less than the upper one.",
"Com o app aberto, o preço é conferido a cada atualização das cotações. Com ele fechado, o celular confere mais ou menos de hora em hora e avisa por notificação (precisa das notificações ligadas e de internet). Não é um aviso em tempo real.":"With the app open, the price is checked on every quote update. With it closed, the phone checks roughly every hour and alerts you with a notification (needs notifications on and internet). It's not a real-time alert.",
"Ex.: Pets":"E.g.: Pets",
"CDI (% a.a.)":"CDI (% p.a.)",
