"da Selic":"of Selic",
"valor inválido":"invalid value",
"Buscando taxas…":"Fetching rates…",
"Não foi possível buscar as taxas. Verifique a internet.":"Couldn't fetch the rates. Check your internet.",
"Oinc!":"Oink!",
"Conta a vencer":"Bill due",
