"A sessão do Google expirou.":"The Google session expired.",
"A senha da conta Google mudou.":"The Google account password changed.",
"Entre de novo com a mesma conta Google.":"Sign in again with the same Google account.",
"O app saiu da conta Google":"The app signed out of the Google account",
"O app não está mais conectado à sua conta Google.":"The app is no longer connected to your Google account.",
"Entre com a sua conta Google.":"Sign in with your Google account.",
"Sem internet ou Wi-Fi sem acesso.":"No internet, or Wi-Fi without access.",
"Modo avião ligado.":"Airplane mode is on.",
"Economia de dados bloqueando o app.":"Data saver blocking the app.",
"Confira a conexão. O que você lançar fica salvo neste aparelho e vai para a conta quando a internet voltar.":"Check your connection. What you add stays saved on this device and goes to the account when the internet is back.",
"Versão mais nova em outro aparelho":"Newer version on another device",
"Outro aparelho usa uma versão mais nova do Cofrim e já gravou os dados nesse formato.":"Another device uses a newer version of Cofrim and has already saved the data in that format.",
"Atualize o app neste aparelho.":"Update the app on this device.",
"Procurar atualização":"Check for updates",
"Dados não encontrados na conta":"Data not found in the account",
"Você entrou com uma conta Google diferente.":"You signed in with a different Google account.",
"Os dados do app foram apagados do Google Drive.":"The app's data was deleted from Google Drive.",
"Confira se é a mesma conta Google de sempre. Se precisar, restaure uma cópia.":"Check that it's the same Google account as always. If needed, restore a backup.",
"Trocar de conta":"Switch account",
"Sincronização pausada":"Sync paused",
"Os dados deste aparelho parecem incompletos perto dos da conta (bem menos lançamentos).":"This device's data looks incomplete compared to the account's (far fewer entries).",
"Para não apagar nada da conta por engano, o app espera você escolher: baixar os dados da conta ou enviar os deste aparelho mesmo assim.":"So as not to delete anything from the account by mistake, the app waits for you to choose: download the account's data or send this device's anyway.",
"Google Drive cheio":"Google Drive full",
"O espaço da sua conta Google acabou.":"Your Google account's storage is full.",
"Libere espaço na conta Google (e-mails, fotos e arquivos grandes) e tente de novo.":"Free up space in your Google account (emails, photos and large files) and try again.",
"Google instável":"Google unstable",
"O Google está instável ou recebeu pedidos demais.":"Google is unstable or received too many requests.",
"Espere alguns minutos: o app tenta de novo sozinho.":"Wait a few minutes: the app tries again on its own.",
"Problema na conta compartilhada":"Shared account problem",
"A conta compartilhada foi encerrada.":"The shared account was closed.",
"O seu acesso a ela foi removido.":"Your access to it was removed.",
"Confira a conta compartilhada nas Configurações (dá para voltar à conta pessoal).":"Check the shared account in Settings (you can go back to your personal account).",
"Abrir conta compartilhada":"Open shared account",
"Erro desconhecido":"Unknown error",
"A causa não foi identificada.":"The cause wasn't identified.",
"Tente de novo. Se continuar, informe o problema para a equipe do Cofrim (o Diagnóstico vai junto).":"Try again. If it continues, report the problem to the Cofrim team (Diagnostics goes along).",
"Possíveis causas":"Possible causes",
"Ver o espaço da conta Google":"See your Google account storage",
"Você está sem internet. Suas alterações ficam salvas e serão sincronizadas quando a conexão voltar.":"You're offline. Your changes stay saved and will sync when the connection is back.",
"Internet de volta":"Internet is back",
"parcela {}/{}":"installment {}/{}",
"sem valor":"no amount",
"sem descrição":"no description",
"Traga os gastos e ganhos de uma planilha que você já usa. O app entende sozinho o jeito dela (uma linha por lançamento, uma aba por mês, blocos por dia, colunas de entrada e saída, cartões lado a lado…) e mostra tudo para você conferir antes de importar.":"Bring in the expenses and income from a spreadsheet you already use. The app figures out its layout on its own (one row per entry, one tab per month, blocks by day, income and expense columns, side-by-side cards…) and shows everything for you to review before importing.",
"Aceita .xlsx (Excel), .ods (LibreOffice) e .csv. No Google Planilhas, baixe antes: Arquivo › Fazer download › Microsoft Excel (.xlsx). O .xls antigo precisa ser salvo de novo como .xlsx.":"Accepts .xlsx (Excel), .ods (LibreOffice) and .csv. In Google Sheets, download first: File › Download › Microsoft Excel (.xlsx). The old .xls must be saved again as .xlsx.",
