"Avisa quando outra pessoa entra na conta ou adiciona/edita um gasto, ganho ou investimento: na tela do app e, com ele fechado, por notificação do celular. O celular confere a cada 15 minutos, mais ou menos (o app não tem servidor para avisar na hora).":"Alerts you when someone joins the account or adds/edits an expense, income or investment: on the app screen and, when it's closed, by phone notification. The phone checks about every 15 minutes (the app has no server to alert instantly).",
