"O app cria uma planilha vazia na sua conta Google e a compartilha com a outra pessoa. Os seus lançamentos de hoje não entram: continuam guardados na sua conta. Depois, ela abre o app e cola o código do convite.":"The app creates an empty spreadsheet in your Google account and shares it with the other person. Your current entries don't go in: they stay saved in your account. Then they open the app and paste the invite code.",
"O app cria uma planilha na sua conta Google com os seus lançamentos e a compartilha com a outra pessoa, que recebe um e-mail do Google. Depois, ela abre o app, entra com a conta convidada e cola o código do convite.":"The app creates a spreadsheet in your Google account with your entries and shares it with the other person, who gets an email from Google. Then they open the app, sign in with the invited account and paste the invite code.",
