"(agora:":"(now:",
"1. Se aparecer \"O Google não verificou este app\", toque em \"Avançado\" e depois em \"Acessar Cofrim (não seguro)\". O aviso aparece porque o app ainda não passou pela verificação do Google; os dados ficam só na sua conta. 2. Marque as caixas de permissão (Planilhas e arquivos do Drive criados pelo app). 3. Toque em \"Continuar\".":"1. If \"Google hasn't verified this app\" appears, tap \"Advanced\" and then \"Go to Cofrim (unsafe)\". The warning appears because the app hasn't gone through Google's verification yet; your data stays only in your account. 2. Check the permission boxes (Sheets and Drive files created by the app). 3. Tap \"Continue\".",
"Agora o Google vai pedir sua permissão para o app criar e ler a planilha da conta compartilhada. {}":"Now Google will ask for your permission for the app to create and read the shared account's spreadsheet. {}",
