"Com \"Sim\", se você gastar menos que o limite de uma categoria ou de um grupo, a diferença soma ao limite dele no mês seguinte.":"With \"Yes\", if you spend less than the limit of a category or a group, the difference adds to its limit the next month.",
"O limite de um grupo soma os gastos de todas as categorias dele e avisa como o das categorias (Configurações › Avisos de valores).":"A group's limit adds up the expenses of all its categories and alerts like the category limits do (Settings › Amount alerts).",
