"Apagar o grupo \"{}\" e as {} categoria(s) dele?":"Delete the group \"{}\" and its {} category(ies)?",
"Nenhum lançamento é apagado: {} lançamento(s) passam para \"Outros\" (ou para a categoria do app com o mesmo nome).":"No entry is deleted: {} entry(ies) move to \"Other\" (or to the built-in category with the same name).",
"As categorias que já vêm no app não se apagam: ficam escondidas em \"Outros\".":"Built-in categories are not deleted: they stay hidden in \"Other\".",
"Restaurar os grupos padrão de gastos?":"Restore the default expense groups?",
"Restaurar os grupos padrão de ganhos?":"Restore the default income groups?",
"Os grupos que vêm no app voltam com o nome, o ícone e a cor deles, e as categorias do app voltam para eles.":"The built-in groups come back with their name, icon and color, and the built-in categories go back to them.",
"Os grupos e as categorias que você criou ficam como estão; nenhum lançamento muda.":"The groups and categories you created stay as they are; no entry changes.",
"Grupos padrão restaurados.":"Default groups restored.",
"Escolher a categoria por grupo":"Choose the category by group",
"Novo ganho ou gasto › Categoria":"New income or expense › Category",
"No topo ficam as categorias usadas por último (um toque escolhe); embaixo, os grupos. Toque num grupo para ver as categorias dele e escolher uma, ou crie uma nova ali mesmo. A busca acha a categoria pelo nome, sem acentos (ex.: \"cafe\" acha Café e lanches); sem resultado, cria com o nome digitado. \"Novo grupo\" cria um grupo sem sair do lançamento, e segurar um grupo (ou uma categoria) abre o Editar e o Excluir. A escolhida aparece como \"Grupo › Categoria\"; toque nela para trocar.":"At the top are the categories you used last (one tap picks one); below, the groups. Tap a group to see its categories and pick one, or create a new one right there. Search finds the category by name, ignoring accents and capital letters; with no results, it creates one with the typed name. \"New group\" creates a group without leaving the entry, and holding a group (or a category) opens Edit and Delete. The chosen one shows as \"Group › Category\"; tap it to change.",
"Grupos de categorias":"Category groups",
"As categorias ficam em grupos (ex.: Lazer reúne Bares, Cinema e Viagens), separados para gastos e ganhos. Toque em um grupo para ver as categorias dele; \"Nova categoria\" cria já dentro do grupo e \"Editar grupo\" muda o nome, o ícone e a cor. Para mudar uma categoria de grupo, use o Editar dela. Ao excluir um grupo, escolha entre mover as categorias para Outros (nada se perde) ou apagá-las também: os lançamentos nunca são apagados. \"Outros\" não se exclui, e \"Restaurar grupos padrão\" traz de volta os grupos do app.":"Categories are organized in groups (e.g., Leisure gathers Bars, Cinema and Travel), separate for expenses and income. Tap a group to see its categories; \"New category\" creates one right inside the group and \"Edit group\" changes its name, icon and color. To move a category to another group, use its Edit. When deleting a group, choose between moving its categories to Other (nothing is lost) or deleting them too: entries are never deleted. \"Other\" can't be deleted, and \"Restore default groups\" brings back the app's groups.",
