"Lançamentos em alguns meses":"Entries in some months",
"Novo ganho ou gasto › Mais opções › Tipo":"New income or expense › More options › Type",
"Para o que não é todo mês nem uma vez por ano: \"A cada X meses\" (PLR a cada 6 meses, em junho e dezembro) conta a partir do primeiro mês; \"Meses escolhidos\" (IPVA em jan, fev e mar) marca os meses numa grade de 12. Os dois aceitam o dia do mês e as regras de dia útil, o vencimento e o \"Até\", e aparecem no grupo \"Em alguns meses\", com uma etiqueta que diz quando repetem. Um anual vira um deles pela edição.":"For what isn't every month or once a year: \"Every X months\" (profit sharing every 6 months, in June and December) counts from the first month; \"Chosen months\" (car tax in Jan, Feb and Mar) marks the months on a 12-month grid. Both take the day of the month and the business day rules, the due date and \"Until\", and show up in the \"In some months\" group, with a tag saying when they repeat. A yearly entry becomes one of them by editing it.",
"No Tipo de um ganho ou gasto, \"A cada X meses\" (ex.: PLR a cada 6 meses, em junho e dezembro) e \"Meses escolhidos\" (ex.: IPVA em jan, fev e mar, numa grade de 12 meses). Contam só nos meses certos, com dia útil e vencimento, e aparecem no grupo \"Em alguns meses\". Importar planilha também sugere esses tipos.":"In an income or expense Type, \"Every X months\" (e.g.: profit sharing every 6 months, in June and December) and \"Chosen months\" (e.g.: car tax in Jan, Feb and Mar, on a 12-month grid). They count only in the right months, with business day and due date, and show up in the \"In some months\" group. Import spreadsheet also suggests these types.",
